mapper.select:
SELECT id, org_id, code_hash, created_by, expires_at, max_uses, used_count, status, created_at
FROM organization_invitation
WHERE id = #{id}

mapper.update:
UPDATE organization_invitation
SET used_count = used_count + 1
WHERE id = #{id}
  AND status = 'ACTIVE'
  AND expires_at > #{now}
  AND used_count < #{maxUses}
